def build_coverage(task):
 mid=int(task['milestone_id'].split('M')[1]); index=int(task['task_id'][-3:]); key=task['task_id'].lower()
 specs=list(SPECS[mid][index-1])
 # Explicit supplemental requirements appended by the task builder.
 for criterion in task['acceptance_criteria'][len(specs):]:
  if criterion.startswith('Use only the explicitly approved platform'):
   specs.append('V+M|Compare platform/renderer/path/test registration to the approved decision and exact build/device receipt; block native implementation when absent.')
  elif criterion.startswith('Prepare evidence for '):
   specs.append('R|Verify accountable approval for the named produced decisions before the dependent native/provider/live-data action; a prepared document alone is not approval.')
  else:raise ValueError('Unmapped acceptance criterion '+task['task_id']+': '+criterion)
 assert len(specs)==len(task['acceptance_criteria'])
 outputs={'U':next((p for p in task['expected_outputs'] if p.endswith('.test.mjs')),None),'D':next((p for p in task['expected_outputs'] if p.endswith('.sql')),None),'B':next((p for p in task['expected_outputs'] if p.endswith('.spec.ts')),None)}
 # Add genuine task-owned tests when review reveals an uncovered data obligation.
 if any('D' in spec.split('|')[0].split('+') for spec in specs) and not outputs['D']:
  outputs['D']=f'apps/doctor-suit/supabase/tests/{key}.sql';task['expected_outputs'].append(outputs['D']);task['allowed_paths'].append('apps/doctor-suit/supabase/tests/')
  task['verification_plan'].append({'version':2,'kind':'planned_test','description':'Verify scoped database criteria with actual disposable authorization/write assertions','expected_outputs':[outputs['D']],'commands':[key+'-data'],'requires':['database','rls-authorization']})
 cases=[];mapping=[]
 for i,(criterion,spec) in enumerate(zip(task['acceptance_criteria'],specs),1):
  modes,procedure=spec.split('|',1);modes=modes.split('+');refs=[];required=[]
  for mode in modes:
   if mode in outputs:
    assert outputs[mode],(task['task_id'],i,mode)
    required.append(outputs[mode]);refs.append(key+'-'+{'U':'unit','D':'data','B':'browser'}[mode])
   elif mode=='C':refs.append('pnpm check')
   elif mode=='L':refs.append('doctor-release-check')
  external=[{'R':'accountable-human-review','M':'approved-platform-device-receipt','V':'independent-exact-candidate-automated-verifier','L':'exact-candidate-release-review'}[m] for m in modes if m in ['R','M','V','L']]
  gates=[]
  if any(m in modes for m in ['R','M','L']):
   gates.append(('criterion_domain_or_device_evidence_required','Only the named domain approvals and actual device/release receipts required by criterion coverage; routine checks require no human acknowledgement.'))
  if 'V' in modes:
   gates.append(('independent_automated_verifier_receipt_required','Machine-produced independent exact-candidate verification receipt for the named coverage cases; automatically evaluate existing evidence and command results. No human acknowledgement or new approval is required.'))
  for blocker,description in gates:
   if not any(v['kind']=='external_gate' and v.get('blocker')==blocker for v in task['verification_plan']):
    task['verification_plan'].append({'version':2,'kind':'external_gate','description':description,'phase':'pre_publication','blocker':blocker})
  cid=task['task_id']+f'-C{i:02d}'
  policy={'human_approval_required':'R' in modes,'independent_automated_verification_required':'V' in modes,'authority_rule':'Verification may validate existing authority and reject missing evidence; it cannot grant, replace or resolve a domain approval.'}
  if 'V' in modes:
   policy['automated_receipt_fields']=['independent verifier execution ID','exact candidate SHA and base SHA','case ID and evaluated input artifact hashes','existing authorization/decision references where relevant','executed command argv, exit codes and immutable logs or reproducible document-comparison assertions','per-assertion result with failed, skipped, unavailable and unrun obligations distinguished']
   policy['missing_evidence_behavior']='Fail or report unavailable verification; never ask for a human acknowledgement as a substitute, invent a decision or perform a held live read.'
  rule='Execute the stated assertions against actual behavior or the exact reviewed documents/receipts. No empty/skipped/source-grep-only/fabricated-pass substitute.'
  if 'R' in modes:rule+=' The genuine domain approval requires accountable reviewer identity, scope/date, exact candidate and supporting references.'
  if 'V' in modes:rule+=' Independent automation must produce the specified exact-candidate receipt; human sign-off is not required for this verification.'
  if 'M' in modes:rule+=' Include actual approved-platform build/device evidence; a unit test cannot replace it.'
  cases.append({'case_id':cid,'criterion_ids':[i],'assertion':criterion,'procedure':procedure,'test_case_name':cid if required else None,'required_outputs':required,'command_refs':refs,'external_evidence_required':bool(external),'evidence_types':external,'evidence_policy':policy,'acceptance_rule':rule})
  mapping.append({'criterion':i,'text':criterion,'verification_case_ids':[cid]})
 # Release evidence is a separate obligation, not indiscriminately attached to every criterion.
 cases.append({'case_id':task['task_id']+'-RELEASE','criterion_ids':[],'assertion':'Task-scoped release provenance and, when applicable, public inventory are complete.','procedure':task['release_contract']['receipt_rule'],'test_case_name':None,'required_outputs':[task['release_contract']['fragment_path']],'command_refs':['doctor-release-check'],'external_evidence_required':True,'evidence_types':['exact-candidate-release-review'],'acceptance_rule':'Preserve unrelated inventory and all accepted fragments; do not activate an operational product.'})
 return cases,mapping
